C     The specification statements, from the examples of chapter 4 of
C     the VAX FORTRAN Language Reference Manual (1988), and appendix A.
      OPTIONS /CHECK=ALL /EXTEND_SOURCE
      PROGRAM SPEC
      IMPLICIT DOUBLE PRECISION (D)
      IMPLICIT COMPLEX (S,Y), LOGICAL*1 (L,A-C)
      PARAMETER (LENGTH=4)
      PARAMETER PI=3.1415927, DPI=3.141592653589793238D0
      CHARACTER*(4+LENGTH) LAST, FIRST
      CHARACTER*32 NAMES(100),SOCSEC(100)*9,NAMETY*10/'ABCDEFGHIJ'/
      INTEGER*2 I, J, K, M12*4, Q, IVEC*4(10)
      REAL*16 QPI/3.14159Q0/, E/2.72Q0/, QARRAY(10)/5*0.0,5*1.0/
      DIMENSION X(5,5,5), Y(4,85), Z(100)
      COMMON HEAT,X /BLK1/KILO,Q
      DOUBLE PRECISION DVAR
      INTEGER*2 IARR(4)
      EQUIVALENCE (DVAR, IARR(1))
      CHARACTER NAME*16, ID*9
      EQUIVALENCE (NAME(10:13), ID(2:5))
      INTEGER A(10), B(10)
      CHARACTER BELL, TAB, LF, FF, STARS*6
      DATA A,STARS /10*0,'****'/
      DATA BELL,TAB,LF,FF /7,9,10,12/
      DATA (B(I), I=1,10,2) /5*1/
      EXTERNAL CTN
      INTRINSIC SIN, COS
      NAMELIST /INPUT/ NAME, GRADE, DATE /OUTPUT/ TOTAL, NAME
      SAVE
      VOLATILE /BLK1/, D, E
CDEC$ PSECT /BLK1/ NOWRT, ALIGN=3
      STRUCTURE /DATE/
          LOGICAL*1 DAY, MONTH
          INTEGER*2 YEAR
      END STRUCTURE
      STRUCTURE /WORDS_LONG/
          UNION
              MAP
                  INTEGER*2 WORD_0, WORD_1, WORD_2
              END MAP
              MAP
                  INTEGER*4 LONG
              END MAP
          END UNION
      END STRUCTURE
      RECORD /DATE/ TODAY,YESTERDAY
      TODAY.YEAR = 1988
      END
      BLOCK DATA BLKDAT
      INTEGER S,X
      LOGICAL T,W
      DOUBLE PRECISION U
      DIMENSION R(3)
      COMMON /AREA1/R,S,T,U /AREA2/W,X,Y
      DATA R/1.0,2*2.0/, T/.FALSE./, U/0.214537D-7/, W/.TRUE./, Y/3.5/
      END
CDEC$ TITLE 'THE END'
